// The window is one complete local day, and the report runs just after it closes.
//
// The brief said 23:00. Running then would leave the last hour of every day in no report
// at all: this report's window would end at 23:00 and the next one would start at the
// following midnight. Running just after midnight over the day that just ended has no gap,
// no overlap, and covers exactly the same day the cap in workflow 12a counts.
const SUPABASE_URL = '';            // TODO: https://<project>.supabase.co
const ALERT_CHAT_ID = '';           // TODO: the Telegram chat that receives the report
const TIMEZONE = 'Europe/Madrid';
const TOP_N = 3;

if (!SUPABASE_URL) throw new Error('SUPABASE_URL is not configured in "Prepare window"');
if (!ALERT_CHAT_ID) throw new Error('ALERT_CHAT_ID is not configured in "Prepare window"');

const base = SUPABASE_URL.replace(/\/+$/, '');
const until = DateTime.now().setZone(TIMEZONE).startOf('day');
const since = until.minus({ days: 1 });

return [{
  json: {
    timezone: TIMEZONE,
    topN: TOP_N,
    chatId: ALERT_CHAT_ID,
    since: since.toISO(),
    until: until.toISO(),
    dayLabel: since.toFormat('cccc d LLLL yyyy'),
    reportUrl: base + '/rest/v1/rpc/llm_spend_report',
  },
}];

// Groups the day into a message. The database already grouped by workflow and model, so
// what arrives here is a handful of rows rather than the whole ledger.
const state = $('Prepare window').first().json;
const res = $input.first().json || {};
const rows = (Array.isArray(res.body) ? res.body : Array.isArray(res) ? res : [])
  .filter((r) => r && r.workflow_name);

const round6 = (n) => Math.round(n * 1e6) / 1e6;
const money = (n) => '$' + (n < 1 ? n.toFixed(4) : n.toFixed(2));

let total = 0;
let calls = 0;
let unpriced = 0;
const byWorkflow = new Map();
const byModel = new Map();

for (const r of rows) {
  const cost = Number(r.cost_usd);
  if (!Number.isFinite(cost) || cost < 0) {
    throw new Error('llm_spend_report returned a cost that is not a number for ' + r.workflow_name);
  }
  total += cost;
  calls += Number(r.calls || 0);
  unpriced += Number(r.unpriced || 0);
  byWorkflow.set(r.workflow_name, round6((byWorkflow.get(r.workflow_name) || 0) + cost));
  byModel.set(r.model, round6((byModel.get(r.model) || 0) + cost));
}
total = round6(total);

// Ties break on the name so two workflows that cost the same do not swap places between
// runs, which would read as movement that did not happen.
const rank = (m) => [...m.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
const workflows = rank(byWorkflow);
const models = rank(byModel);
const top = workflows.slice(0, state.topN);

const share = (n) => (total > 0 ? ' (' + Math.round((n / total) * 100) + '%)' : '');
const lines = [
  'LLM spend, ' + state.dayLabel,
  'Total: ' + money(total) + ' over ' + calls + ' call' + (calls === 1 ? '' : 's'),
  '',
  'Most expensive workflows:',
  ...top.map(([name, cost], i) => '  ' + (i + 1) + '. ' + name + '  ' + money(cost) + share(cost)),
];
if (workflows.length > top.length) {
  const rest = round6(workflows.slice(top.length).reduce((s, [, c]) => s + c, 0));
  lines.push('  and ' + (workflows.length - top.length) + ' more, ' + money(rest) + ' together');
}
lines.push('', 'By model:');
for (const [name, cost] of models) lines.push('  ' + name + '  ' + money(cost) + share(cost));
if (unpriced > 0) {
  lines.push('', unpriced + ' call' + (unpriced === 1 ? '' : 's')
    + ' used a model with no price, recorded at zero. The real total is higher than this.');
}

return [{
  json: {
    ...state,
    total,
    calls,
    unpriced,
    workflows: workflows.map(([name, cost]) => ({ workflow_name: name, cost_usd: cost })),
    models: models.map(([name, cost]) => ({ model: name, cost_usd: cost })),
    top: top.map(([name, cost]) => ({ workflow_name: name, cost_usd: cost })),
    hasSpend: rows.length > 0,
    message: lines.join('\n'),
  },
}];
